ALTER TABLE "app"."course_centre" ADD CONSTRAINT "course_centre_centre_id_fkey" FOREIGN KEY ("centre_id") REFERENCES "app"."centre"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- ---------- Named checks (mirrored in src/server/catalogue.ts) ----------
alter table app.certification add constraint certification_code_check check (code ~ '^[!-~]+( [!-~]+)*$' and code = upper(code) and length(code) <= 30);
alter table app.certification add constraint certification_name_check check (name = btrim(name) and char_length(name) between 1 and 200);
alter table app.certification add constraint certification_type_check check (type in ('VOUCHER', 'LICENCE'));
-- the multiline rule of ownText(): the JS trim() whitespace set written out, tab/LF/CR allowed (as 0018's follow-up note)
do $$
declare
  ws constant text := '[\t\n\v\f\r    -     　﻿]';
  ctl_address constant text := '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]'; -- tab, newline, carriage return allowed
begin
  execute format('alter table app.certification add constraint certification_description_check check (description !~ %L and description !~ %L and description !~ %L and char_length(description) between 1 and 1000)',
    '^' || ws, ws || '$', ctl_address);
end $$;

-- ---------- RLS ----------
-- certification: the 0012 setup pattern (everyone reads; catalogue.manage at ALL scope writes; no delete)
alter table app.certification enable row level security;
alter table app.certification force row level security;
create policy setup_select on app.certification for select using (true);
create policy setup_insert on app.certification for insert with check ((select app.has_permission('catalogue.manage', null)));
create policy setup_update on app.certification for update using ((select app.has_permission('catalogue.manage', null)))
  with check ((select app.has_permission('catalogue.manage', null)));
-- course_certification: as course_centre_class (0016)
alter table app.course_certification enable row level security;
alter table app.course_certification force row level security;
create policy setup_select on app.course_certification for select using (true);
create policy setup_insert on app.course_certification for insert with check ((select app.has_permission('catalogue.manage', null)));
create policy setup_delete on app.course_certification for delete using ((select app.has_permission('catalogue.manage', null)));
-- course_centre has centre_id, so T-RLS-002 wants all four commands. D5: catalogue data, readable by every session;
-- centre names stay gated by app.centre's own RLS. No update grant, so the update policy can never be used.
alter table app.course_centre enable row level security;
alter table app.course_centre force row level security;
create policy course_centre_select on app.course_centre for select using (true);
create policy course_centre_insert on app.course_centre for insert with check ((select app.has_permission('catalogue.manage', null)));
create policy course_centre_update on app.course_centre for update using ((select app.has_permission('catalogue.manage', null)))
  with check ((select app.has_permission('catalogue.manage', null)));
create policy course_centre_delete on app.course_centre for delete using ((select app.has_permission('catalogue.manage', null)));

-- ---------- Grants (the code never changes; links are replaced as a set) ----------
grant select, insert on app.certification to gems_app;
grant update (name, type, description, active) on app.certification to gems_app;
grant select, insert, delete on app.course_certification, app.course_centre to gems_app;
grant usage on sequence app.certification_id_seq to gems_app;
